-- J01-J04 baseline schema, generated from the Hibernate mappings.
-- Do not edit this file after it has been applied; add V2__*.sql instead.

create table accepted_import (
    listing_count integer not null,
    offer_count integer not null,
    product_count integer not null,
    source_date date,
    id bigint not null,
    retrieved_at timestamp(6) with time zone not null,
    origin varchar(16) not null,
    checksum varchar(64) not null,
    source_url varchar(500) not null,
    primary key (id)
);

create table products (
    active boolean not null,
    code varchar(80) not null,
    brand_en varchar(255),
    brand_zh_hans varchar(255),
    brand_zh_hant varchar(255),
    category1_en varchar(255),
    category1_zh_hans varchar(255),
    category1_zh_hant varchar(255),
    category2_en varchar(255),
    category2_zh_hans varchar(255),
    category2_zh_hant varchar(255),
    category3_en varchar(255),
    category3_zh_hans varchar(255),
    category3_zh_hant varchar(255),
    name_en varchar(255),
    name_zh_hans varchar(255),
    name_zh_hant varchar(255),
    primary key (code)
);

create table retailer_listings (
    price numeric(19,4),
    id bigint generated by default as identity,
    product_code varchar(80) not null,
    retailer_code varchar(80) not null,
    primary key (id),
    constraint uk_listing_product_retailer unique (product_code, retailer_code)
);

create table retailer_offers (
    id bigint generated by default as identity,
    listing_id bigint not null,
    offer_en varchar(1000),
    offer_zh_hans varchar(1000),
    offer_zh_hant varchar(1000),
    primary key (id)
);

create table shopping_lists (
    id bigint generated by default as identity,
    name varchar(100) not null unique,
    primary key (id)
);

create table shopping_list_items (
    checked boolean not null,
    quantity integer not null,
    id bigint generated by default as identity,
    shopping_list_id bigint not null,
    product_code varchar(80) not null,
    selected_retailer_code varchar(80),
    primary key (id),
    constraint uk_list_item_product unique (shopping_list_id, product_code)
);

alter table retailer_listings
    add constraint fk_retailer_listings_product foreign key (product_code) references products;
alter table retailer_offers
    add constraint fk_retailer_offers_listing foreign key (listing_id) references retailer_listings;
alter table shopping_list_items
    add constraint fk_shopping_list_items_product foreign key (product_code) references products;
alter table shopping_list_items
    add constraint fk_shopping_list_items_list foreign key (shopping_list_id) references shopping_lists;
